"""Measure current breastcollar vertices against deformed upper forelimbs; no model edits."""
import json,pathlib
from playwright.sync_api import sync_playwright
P=pathlib.Path(__file__).parent
with sync_playwright() as p:
 b=p.chromium.launch(executable_path='/usr/bin/chromium',headless=True,args=['--no-sandbox','--use-angle=swiftshader','--enable-unsafe-swiftshader']);page=b.new_page(viewport={'width':1280,'height':800});page.goto('http://127.0.0.1:8774/renderers/web/transport/horse/');page.wait_for_function('window.fixture?.ready');page.evaluate('fixture.pause();fixture.setClip("idle");fixture.setPhase(0)')
 data=page.evaluate("""async()=>{
 const T=await import('../../vendor/three-0.185.1/three.module.js');const {GLTFLoader}=await import('../../vendor/three-0.185.1/addons/loaders/GLTFLoader.js');
 const manifest=await(await fetch('manifest.json')).json(),params=await(await fetch('../../../../data/transport/studies/harness.json')).json();const ranges=manifest.vertex_ranges.filter(r=>/^fore_[lr]_upper_mesh$/.test(r.original_node));const harness=await new GLTFLoader().loadAsync('../harness/light_breastcollar_harness_reconstructed_01.glb');harness.scene.updateMatrixWorld(true);const collar=harness.scene.getObjectByName('breastcollar');const garment=[];for(let i=0;i<collar.geometry.attributes.position.count;i++)garment.push(new T.Vector3().fromBufferAttribute(collar.geometry.attributes.position,i).applyMatrix4(collar.matrixWorld));
 const m=fixture.horse.getObjectByName('skinned_equine_coat'),g=m.geometry;
 function triangles(){m.skeleton.update();fixture.horse.updateMatrixWorld(true);const ts=[];for(let i=0;i<g.index.count;i+=3){const ids=[0,1,2].map(j=>g.index.getX(i+j));if(ranges.some(range=>ids.every(id=>id>=range.vertex_start&&id<range.vertex_start+range.vertex_count)))ts.push({ids,tri:new T.Triangle(...ids.map(id=>m.getVertexPosition(id,new T.Vector3()).applyMatrix4(m.matrixWorld)))});}return ts;}
 const collarTriangles=[];for(let i=0;i<garment.length;i+=3)collarTriangles.push(new T.Triangle(garment[i],garment[i+1],garment[i+2]));
 function bounds(t){return new T.Box3().setFromPoints([t.a,t.b,t.c]);}
 function overlapSAT(a,b){const av=[a.a,a.b,a.c],bv=[b.a,b.b,b.c],ae=[a.b.clone().sub(a.a),a.c.clone().sub(a.b),a.a.clone().sub(a.c)],be=[b.b.clone().sub(b.a),b.c.clone().sub(b.b),b.a.clone().sub(b.c)],an=a.getNormal(new T.Vector3()),bn=b.getNormal(new T.Vector3()),axes=[an,bn];for(const e of ae)for(const f of be)axes.push(e.clone().cross(f));for(const e of ae)axes.push(an.clone().cross(e));for(const e of be)axes.push(bn.clone().cross(e));for(const axis of axes){if(axis.lengthSq()<1e-20)continue;axis.normalize();const aa=av.map(p=>p.dot(axis)),bb=bv.map(p=>p.dot(axis));if(Math.max(...aa)<Math.min(...bb)-1e-8||Math.max(...bb)<Math.min(...aa)-1e-8)return false;}return true;}
 function intersections(ts){let candidates=0,hits=[];for(let i=0;i<collarTriangles.length;i++){const a=collarTriangles[i],ab=bounds(a);for(let j=0;j<ts.length;j++){const b=ts[j].tri;if(!ab.intersectsBox(bounds(b)))continue;candidates++;if(overlapSAT(a,b))hits.push({collar_triangle:i,upper_forelimb_triangle:j,upper_forelimb_vertex_ids:ts[j].ids});}}return{triangle_aabb_candidates:candidates,triangle_intersections:hits.length,intersecting_pairs:hits};}
 function nearest(pt,ts){let best={distance_m:Infinity};for(const {ids,tri} of ts){const q=tri.closestPointToPoint(pt,new T.Vector3()),distance=pt.distanceTo(q);if(distance<best.distance_m){const n=tri.getNormal(new T.Vector3()),signed=pt.clone().sub(q).dot(n);best={distance_m:distance,point_m:q.toArray(),normal:n.toArray(),signed_triangle_plane_distance_m:signed,signed_nearest_distance_m:Math.sign(signed)*distance,suggested_outer_route_10mm_m:q.clone().addScaledVector(n,.010).toArray(),triangle_vertex_ids:ids};}}return best;}
 fixture.setClip('idle');fixture.setPhase(0);let ts=triangles();const samples=params.breastcollar_route_m.map(x=>({route_m:x,...nearest(new T.Vector3(...x),ts)}));const phases=[];
 for(const clip of ['idle','walk'])for(let i=0;i<(clip==='idle'?1:101);i++){
  const phase=clip==='idle'?0:i/100;fixture.setClip(clip);fixture.setPhase(phase);const ts=triangles();let low={signed_nearest_distance_m:Infinity},high={signed_nearest_distance_m:-Infinity},penetrating=0;
  for(let j=0;j<garment.length;j++){const v=garment[j],n=nearest(v,ts);if(n.signed_nearest_distance_m<low.signed_nearest_distance_m)low={vertex_index:j,vertex_m:v.toArray(),...n};if(n.signed_nearest_distance_m>high.signed_nearest_distance_m)high={vertex_index:j,vertex_m:v.toArray(),...n};if(n.signed_nearest_distance_m<-.001)penetrating++;}
  const upper_forelimb_max_y_m=Math.max(...ts.flatMap(t=>[t.tri.a.y,t.tri.b.y,t.tri.c.y]));const collar_min_y_m=Math.min(...garment.map(v=>v.y));const collision=intersections(ts);phases.push({...collision,clip,phase,upper_forelimb_max_y_m,collar_min_y_m,vertical_aabb_gap_m:collar_min_y_m-upper_forelimb_max_y_m,vertex_samples:garment.length,vertices_with_signed_distance_below_minus_1mm:penetrating,min:low,max:high});
 }
 return{asset:manifest.asset_id,upper_forelimb_ranges:ranges,samples,width_aware:{method:'all actual breastcollar mesh vertices against actual skinned upper forelimb triangles; sign from nearest face normal, not a watertight inside test; separate full triangle-pair AABB+SAT intersection test included for selected upper limbs only',phases,min_signed_distance_m:Math.min(...phases.map(p=>p.min.signed_nearest_distance_m)),max_signed_distance_m:Math.max(...phases.map(p=>p.max.signed_nearest_distance_m)),min_vertical_aabb_gap_m:Math.min(...phases.map(p=>p.vertical_aabb_gap_m))}};
}""");b.close()
(P/'forelimb-clearance.json').write_text(json.dumps(data,indent=2)+'\n');assert all(p['triangle_intersections']==0 for p in data['width_aware']['phases']), 'Actual collar/upper-forelimb triangle intersections found in selected sampled poses';print(json.dumps({'route_samples':data['samples'],'width_aware_summary':{k:v for k,v in data['width_aware'].items() if k!='phases'}},indent=2))
